import frappe
MARK='<!-- INVENTORY COMMUNICATION DEFAULT v2 -->'
def html(title_en,title_ar,lead_en,lead_ar):
 return MARK+f'''{{% set primary = '#176b87' %}}{{% if company %}}{{% set primary = frappe.db.get_value('Company', company, 'custom_primary_color') or primary %}}{{% endif %}}<div style="margin:0;padding:0;background:#eef2f5;font-family:Arial,Tahoma,sans-serif;color:#263238;line-height:1.7"><div style="max-width:760px;margin:0 auto;padding:24px 10px"><div style="background:#fff;border:1px solid #d9e1e5;border-radius:12px;overflow:hidden;box-shadow:0 3px 12px rgba(20,55,70,.08)"><div style="background:{{{{ primary }}}};padding:26px;text-align:center;color:#fff"><div style="font-size:22px;font-weight:700;direction:ltr">{title_en}</div><div style="font-size:18px;margin-top:5px;direction:rtl">{title_ar}</div></div><div style="padding:28px"><div dir="ltr"><p>Dear Recipient,</p><p>{lead_en}</p></div><div style="height:1px;background:#e6eaee;margin:18px 0"></div><div dir="rtl" style="text-align:right"><p>السيد/السيدة المستلم المحترم،</p><p>{lead_ar}</p></div><table width="100%" style="border-collapse:collapse;background:#f7f9fb;border:1px solid #e1e7eb;margin-top:18px"><tr><td style="padding:8px"><b>Reference | المرجع</b></td><td style="padding:8px">{{{{ name or doc.name }}}}</td></tr><tr><td style="padding:8px"><b>Status | الحالة</b></td><td style="padding:8px">{{{{ custody_status or handover_status or incident_status or approval_status or custom_receipt_acceptance_status or '' }}}}</td></tr></table><div style="text-align:center;margin-top:24px"><a href="{{{{ record_url or frappe.utils.get_url_to_form(doc.doctype,doc.name) }}}}" style="display:inline-block;background:{{{{ primary }}}};color:#fff;text-decoration:none;padding:11px 20px;border-radius:5px;font-weight:700">Open Record | فتح السجل</a></div><p style="font-size:12px;color:#667085;text-align:center;margin-top:22px">Official system communication. | مراسلة رسمية صادرة من النظام.</p></div></div></div></div>'''
TEMPLATES={
'Stock Handover Notice':('Stock handover requires acknowledgement: {{ name }}','Stock Handover','إقرار تسليم المواد','A stock handover is ready for acknowledgement.','أصبح محضر تسليم المواد جاهزا للإقرار.'),
'Asset Custody Notice':('Asset custody assigned: {{ name }}','Asset Custody','إقرار عهدة أصل','An asset custody record requires your acknowledgement.','يتطلب سجل عهدة الأصل إقرارك بالاستلام والمسؤولية.'),
'Asset Incident Notice':('Asset incident requires action: {{ name }}','Asset Incident','حادث أصل يتطلب إجراء','An incident record requires review and corrective action.','يتطلب سجل الحادث المراجعة والإجراء التصحيحي.'),
'Custody Return Reminder':('Custody return reminder: {{ name }}','Custody Return Reminder','تذكير بإعادة العهدة','The asset return date is approaching or overdue.','اقترب موعد إعادة العهدة أو أصبح متأخرا.'),
'Inspection Due Reminder':('Receipt inspection due: {{ name }}','Receipt Inspection Due','فحص استلام مستحق','A receipt requires inspection or follow-up.','يتطلب سند الاستلام إجراء الفحص أو المتابعة.'),
'Verification Approval Notice':('Verification pending approval: {{ name }}','Verification Approval','اعتماد الجرد الفعلي','A physical verification record is ready for approval.','أصبح سجل الجرد الفعلي جاهزا للاعتماد.'),
}
def provision_communications():
 for name,(subject,en,ar,lead_en,lead_ar) in TEMPLATES.items():
  existing=frappe.db.exists('Email Template',name)
  if not existing:frappe.get_doc({'doctype':'Email Template','name':name,'subject':subject,'use_html':1,'response_html':html(en,ar,lead_en,lead_ar)}).insert(ignore_permissions=True)
 notices=[('Receipt Inspection Required','Purchase Receipt','custom_receipt_acceptance_status',"doc.custom_receipt_acceptance_status == 'Pending Inspection'",'Stock Manager',None),('Handover Acknowledgement Pending','Stock Handover','handover_status',"doc.handover_status == 'Pending Handover'",None,'recipient_user'),('Handover Discrepancy Review','Stock Handover','discrepancy_status',"doc.discrepancy_status == 'Open'",'Stock Manager',None),('Incident Decision Pending','Asset Incident','incident_status',"doc.incident_status == 'Decision Pending'",'Stock Manager',None),('Verification Approval Pending','Physical Verification','approval_status',"doc.approval_status == 'Pending Approval'",'Stock Manager',None)]
 for name,dt,field,condition,role,docfield in notices:
  if frappe.db.exists('Notification',name):continue
  d=frappe.get_doc({'doctype':'Notification','name':name,'document_type':dt,'channel':'Email','enabled':1,'event':'Value Change','value_changed':field,'condition':condition,'subject':name+': {{ doc.name }}','message':html(name,name,'Please review the linked record.','يرجى مراجعة السجل المرتبط.')});d.append('recipients',{'receiver_by_role':role} if role else {'receiver_by_document_field':docfield});d.insert(ignore_permissions=True)
